fn seqxml_escape_attr(s : String) -> String {
  s
  .replace(old="&", new="&amp;")
  .replace(old="<", new="&lt;")
  .replace(old=">", new="&gt;")
  .replace(old="\"", new="&quot;")
  .replace(old="'", new="&apos;")
}

///|
/// Escape a string for use as XML text content.
fn seqxml_escape_text(s : String) -> String {
  s
  .replace(old="&", new="&amp;")
  .replace(old="<", new="&lt;")
  .replace(old=">", new="&gt;")
}

fn main {
 println(seqxml_escape_attr("&&"))
 println(seqxml_escape_text("<<"))
}
